/* eslint-disable @typescript-eslint/ban-types */

export type variantType = 'base' | 'navigation' | 'selectable';
export type spacingType = 'none' | 'medium' | 'large';

type AsProp<C extends React.ElementType> = {
  as?: C;
};

type PropsToOmit<C extends React.ElementType, P> = keyof (AsProp<C> & P);

// Reusable type for component props
type PolymorphicComponentProp<C extends React.ElementType, Props = {}> = React.PropsWithChildren<
  Props & AsProp<C>
> &
  Omit<React.ComponentPropsWithoutRef<C>, PropsToOmit<C, Props>>;

// Utility type for component props with ref
type PolymorphicComponentPropWithRef<
  C extends React.ElementType,
  Props = {}
> = PolymorphicComponentProp<C, Props> & { ref?: PolymorphicRef<C> };

// This is the type for the "ref" only
export type PolymorphicRef<C extends React.ElementType> = React.ComponentPropsWithRef<C>['ref'];

/**
 * This is the component props using PolymorphicComponentPropWithRef
 */
export type ListItemProps<C extends React.ElementType> = PolymorphicComponentPropWithRef<
  C,
  {
    variant?: variantType;
    divider?: boolean;
    spacing?: spacingType;
    children?: React.ReactNode;
    disabled?: boolean;
  }
>;

/**
 * This is the type used in the type annotation for the component
 */
export type ListItemComponent = <C extends React.ElementType = 'li'>(
  props: ListItemProps<C>
) => React.ReactElement | null;
